// Carrega contrato de calibração do candidato
return [
  {
    json: {
      profile_owner: "Mauricio Alves dos Santos",
      target_seniority: "Senior / Lead Architect",
      cargos_alvo: [
        "SRE Manager",
        "Automation Architect",
        "Workload Automation Specialist",
        "Infrastructure Engineer - AI & Cloud",
        "Analista de Produção e Operações de TI SR",
        "Scheduler SR"
      ],
      skills_obrigatorias: [
        "Control-M", "UC4 (Automic)", "Maestro", 
        "TSM (Tivoli Storage Manager)", "NetBackup", 
        "Mainframe ES9000 / VM/VSESA", "Tape Libraries (ACSLS)", 
        "UNIX (AIX, Solaris, HP-UX, Linux)", "SAP R/3 Basis"
      ],
      skills_modernas: [
        "Python", "CrewAI", "N8N", "AWS Cloud Practitioner", 
        "Azure AZ-900 / AI-900", "Kubernetes"
      ],
      major_accounts: ["TECBAN", "ENEL", "BUNGE", "UNILEVER", "FABER-CASTELL"],
      thresholds: {
        high_match: 70,
        correction_min: 50
      }
    }
  }
];

// Anti-Fraud Gate: Filosofia Fail-Closed
const items = $input.all();
const output = [];

const freeEmailDomains = ['gmail.com', 'hotmail.com', 'yahoo.com', 'outlook.com', 'bol.com.br'];
const fraudPatterns = [
  /taxa\s+(de\s+)?(inscri[cç][aã]o|processo|sele[cç][aã]o)/i,
  /pagar\s+(pelo\s+)?(curso|treinamento|exame)/i,
  /chave\s+pix|dep[oó]sito/i,
  /envie\s+(foto\s+do\s+)?(documento|rg|cpf|cnh|cart[aã]o)/i,
  /renda\s+extra\s+di[aá]ria/i
];

for (const entry of items) {
  const item = entry.json;
  let isFraud = false;
  let reason = '';

  const email = (item.contact_email || '').toLowerCase();
  const domain = email.split('@')[1];
  if (domain && freeEmailDomains.includes(domain)) {
    isFraud = true;
    reason = `Domínio de e-mail gratuito (${domain}) em vaga corporativa`;
  }

  const text = `${item.title || ''} ${item.description || ''}`.toLowerCase();
  for (const pat of fraudPatterns) {
    if (pat.test(text)) {
      isFraud = true;
      reason = `Gatilho de risco detectado: ${pat.toString()}`;
      break;
    }
  }

  if (item.whois_age_days !== undefined && item.whois_age_days < 30) {
    isFraud = true;
    reason = 'Domínio com menos de 30 dias de registro';
  }

  output.push({
    json: {
      ...item,
      security_passed: !isFraud,
      fraud_reason: reason,
      processed_at: new Date().toISOString()
    }
  });
}

return output;

// Motor de Match Semântico e Metrologia de Aderência
const profile = $('Loader: profile.json').first().json;
const jobRaw = $input.first().json;
let parsed = {};

try {
  parsed = typeof jobRaw.message?.content === 'string' ? JSON.parse(jobRaw.message.content) : jobRaw;
} catch (e) {
  parsed = jobRaw;
}

const jobStack = (parsed.stack_tecnica || []).map(s => s.toLowerCase());
const reqs = (parsed.requisitos_obrigatorios || []).map(r => r.toLowerCase());
const fullJob = `${parsed.cargo_normalizado || ''} ${jobStack.join(' ')} ${reqs.join(' ')}`.toLowerCase();

// 1. Cálculo de Hard Skills Core (Control-M, TSM, Mainframe, UNIX, etc.)
let coreMatches = 0;
for (const skill of profile.skills_obrigatorias) {
  if (fullJob.includes(skill.toLowerCase())) {
    coreMatches++;
  }
}
const coreScore = (coreMatches / Math.max(1, profile.skills_obrigatorias.length)) * 100;

// 2. Cálculo de Modern Skills (Python, CrewAI, Cloud, Kubernetes)
let modernMatches = 0;
for (const skill of profile.skills_modernas) {
  if (fullJob.includes(skill.toLowerCase())) {
    modernMatches++;
  }
}
const modernScore = (modernMatches / Math.max(1, profile.skills_modernas.length)) * 100;

// 3. Ponderação de Senioridade e Missão Crítica
const missionCriticalBonus = parsed.sla_missao_critica ? 20 : 0;
const finalScore = Math.min(100, Math.round((coreScore * 0.55) + (modernScore * 0.25) + missionCriticalBonus + 15));

let status = 'BAIXA';
if (finalScore >= profile.thresholds.high_match) {
  status = 'ALTA_PRIORIDADE';
} else if (finalScore >= profile.thresholds.correction_min) {
  status = 'LOOP_CORRECAO';
}

return [
  {
    json: {
      ...parsed,
      match_score: finalScore,
      status: status,
      candidato: profile.profile_owner,
      job_title: parsed.cargo_normalizado || $('Filtro: Vaga Segura?').first().json.title,
      company: $('Filtro: Vaga Segura?').first().json.company || 'Empresa Confidencial',
      evaluated_at: new Date().toISOString()
    }
  }
];

